export type DateOutcome = "great" | "good" | "awkward";
export type PlayerSex = "femme" | "homme" | "intersexe";
export type IntimacyMode = "tendre" | "suggestif" | "explicite" | "ellipse";

export type DateScene = {
  id: string;
  character: string;
  title: string;
  type: string;
  description: string;
  location: string;
  spot: string;
  period: PeriodKey;
  unlockStage: number;
  minAffection: number;
  minTrust: number;
  /** Seuil vérifié uniquement après le rendez-vous pour proposer l’intimité. */
  minDesire?: number;
  mood: string;
  intro: DialogueLine[];
  choices: ChoiceData[];
  intimacySetting: {
    opening: string[];
    closing: string[];
    /** Le rendez-vous possède une continuité intime complète et ne reçoit pas le prologue générique du personnage. */
    replaceProfile?: boolean;
  };
};

const line = (speaker: string, text: string, mood?: string): DialogueLine => ({ speaker, text, mood });
const dateChoice = (
  id: string,
  text: string,
  stat: StatKey,
  response: DialogueLine[],
  outcome: DateOutcome,
  effects: Effects,
): ChoiceData => ({
  id,
  text,
  stat,
  response,
  dateOutcome: outcome,
  effects: { ...effects, stats: { ...(effects.stats || {}), [stat]: 1 } },
});

